class BytesIOCopy:
    """A ``BytesIO``-like object, backed by a real temporary file so that
    it exposes a valid ``fileno()``, whose written data is also copied
    to another stream.

    A real file descriptor is needed so that code under test can pass
    ``sys.stdout``/``sys.stderr`` to APIs (such as
    :func:`subprocess.run`) that require a file-like object with a
    ``fileno()``.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data


