class BytesIOCopy(io.BytesIO):
    """Patch ``io.BytesIO`` to let the written stream be copied to another.

    A real, on-disk file is lazily created the first time ``fileno()`` is
    accessed, so that code under test can pass ``sys.stdout``/``sys.stderr``
    to APIs (such as :func:`subprocess.run`) that require a file-like
    object with a valid file descriptor.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._fileno_file: t.IO[bytes] | None = None

    def fileno(self) -> int:
        if self._fileno_file is None:
            self._fileno_file = tempfile.TemporaryFile()
            self._fileno_file.write(self.getvalue())
            self._fileno_file.flush()

        return self._fileno_file.fileno()

    def flush(self) -> None:
        super().flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)

        if self._fileno_file is not None:
            self._fileno_file.write(b)

        return super().write(b)

    def close(self) -> None:
        if self._fileno_file is not None:
            self._fileno_file.close()

        super().close()

